import { NextRequest, NextResponse } from 'next/server';
import { appendLead } from '@/lib/excel';

function sanitize(input: unknown, maxLength: number): string {
  if (typeof input !== 'string') return '';
  return input.replace(/\s+/g, ' ').trim().slice(0, maxLength);
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();

    const name = sanitize(body.name, 200);
    const email = sanitize(body.email, 200);
    const phone = sanitize(body.phone, 100);
    const broker = sanitize(body.broker, 200);
    const message = sanitize(body.message ?? '', 2000);

    if (!name || !email || !phone || !broker) {
      return NextResponse.json(
        { success: false, error: 'Missing required fields.' },
        { status: 400 }
      );
    }

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
      return NextResponse.json(
        { success: false, error: 'Invalid email address.' },
        { status: 400 }
      );
    }

    appendLead({
      name,
      email,
      phone,
      broker,
      message,
      timestamp: new Date().toISOString()
    });

    return NextResponse.json({ success: true });
  } catch (error) {
    return NextResponse.json(
      { success: false, error: 'Unexpected error while processing request.' },
      { status: 500 }
    );
  }
}

